using UnityEngine;using UnityEngine.Rendering.HighDefinition;
public static class CapturePickups{public static string Main(){var go=new GameObject("Pickup preview camera");var c=go.AddComponent<Camera>();c.enabled=false;c.nearClipPlane=.01f;go.AddComponent<HDAdditionalCameraData>();var rt=RenderTexture.GetTemporary(1100,800,24);var old=RenderTexture.active;var tex=new Texture2D(1100,800,TextureFormat.RGB24,false);try{foreach(var p in Object.FindObjectsByType<PickupController>(FindObjectsSortMode.None)){var b=p.GetComponent<BicycleController>();foreach(bool inside in new[]{true,false}){c.fieldOfView=inside?70:45;if(inside){go.transform.SetPositionAndRotation(b.riderView.position,p.transform.rotation*Quaternion.Euler(b.RidingCameraPitch,0,0));}else{go.transform.position=p.transform.TransformPoint(new Vector3(-6,4,7));go.transform.LookAt(p.transform.TransformPoint(Vector3.up));}c.targetTexture=rt;c.Render();c.Render();RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,1100,800),0,0);tex.Apply();System.IO.File.WriteAllBytes("output/Pickups/"+p.name+(inside?" driver":" exterior")+".png",tex.EncodeToPNG());}}return "Captured all pickup driver/exterior views";}finally{c.targetTexture=null;RenderTexture.active=old;RenderTexture.ReleaseTemporary(rt);Object.DestroyImmediate(tex);Object.DestroyImmediate(go);}}}
